                                                                                                                                                                                                        
  CREATE TABLE "TENANT_PROJECT"                                                                                                                                                              
   (	"PROJECT_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                             
	"CREATION_DATE" DATE DEFAULT SYSDATE NOT NULL ENABLE,                                                                                                                                                  
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                             
	"UPDATE_DATE" DATE DEFAULT SYSDATE NOT NULL ENABLE,                                                                                                                                                    
	"REMARK" NVARCHAR2(512),                                                                                                                                                                               
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                    
	"PROJECT_NAME" NVARCHAR2(50) NOT NULL ENABLE,                                                                                                                                                          
	"PROJECT_CODE" NVARCHAR2(50) NOT NULL ENABLE,                                                                                                                                                          
	"PROVIDER_NAME" NVARCHAR2(100) NOT NULL ENABLE,                                                                                                                                                        
	"PROVIDER_LEADER_NAME" NVARCHAR2(100) NOT NULL ENABLE,                                                                                                                                                 
	"PROVIDER_LEADER_MOBILE" NVARCHAR2(100) NOT NULL ENABLE,                                                                                                                                               
	"IS_ENABLE" NUMBER DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                          
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                          
	 PRIMARY KEY ("PROJECT_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                   
   ) ;                                                                                                                                                                                                  

